import static org.junit.Assert.*;

public class FitnessFunction_encode_TriageGen2Test {

    /**
     * Helper method to inject boundaries into the private field 'boundaries' 
     * of the FitnessFunction class using reflection, as it is not exposed via a setter.
     */
    private void setBoundaries(org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction fitnessFunction, double[][] boundaries) throws Exception {
        Field field = org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction.class.getDeclaredField("boundaries");
        field.setAccessible(true);
        field.set(fitnessFunction, boundaries);
    }

    @Test
    public void testEncode_BoundariesIsNull() {
        org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction fitnessFunction = 
            new org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction();

        double[] x = {1.0, 2.0, 3.0};
        double[] result = fitnessFunction.encode(x);

        // When boundaries is null, it should return the same array reference or same values
        Assert.assertArrayEquals(x, result, 1e-10);
    }

    @Test
    public void testEncode_NormalOperation() throws Exception {
        org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction fitnessFunction = 
            new org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction();

        // boundaries[0] is min, boundaries[1] is max
        double[][] boundaries = {
            {0.0, 10.0, -5.0}, // min
            {10.0, 20.0, 5.0}  // max
        };
        setBoundaries(fitnessFunction, boundaries);

        double[] x = {5.0, 15.0, 0.0};
        // Expected: (5-0)/(10-0) = 0.5; (15-10)/(20-10) = 0.5; (0-(-5))/(5-(-5)) = 5/10 = 0.5
        double[] expected = {0.5, 0.5, 0.5};

        double[] result = fitnessFunction.encode(x);

        Assert.assertArrayEquals(expected, result, 1e-10);
    }

    @Test
    public void testEncode_BoundaryValues() throws Exception {
        org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction fitnessFunction = 
            new org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction();

        double[][] boundaries = {
            {0.0, 100.0},
            {10.0, 110.0}
        };
        setBoundaries(fitnessFunction, boundaries);

        // Test x at min boundaries
        double[] xMin = {0.0, 100.0};
        double[] expectedMin = {0.0, 0.0};
        Assert.assertArrayEquals(expectedMin, fitnessFunction.encode(xMin), 1e-10);

        // Test x at max boundaries
        double[] xMax = {10.0, 110.0};
        double[] expectedMax = {1.0, 1.0};
        Assert.assertArrayEquals(expectedMax, fitnessFunction.encode(xMax), 1e-10);
    }

    @Test
    public void testEncode_EmptyArray() throws Exception {
        org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction fitnessFunction = 
            new org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction();

        double[][] boundaries = {
            {},
            {}
        };
        setBoundaries(fitnessFunction, boundaries);

        double[] x = {};
        double[] result = fitnessFunction.encode(x);

        Assert.assertEquals(0, result.length);
    }
}
